22	/**
23	 * Checks declared headings and file declarations using shared structured inputs.
24	 */
25	final class HeadingStructure implements Policy
26	{
27	    /**
28	     * Creates the HeadingStructure with its declared dependencies.
29	     */
30	    public function __construct(private DocumentationConfig $config)
31	    {
32	    }
33	    /**
34	     * @return array<string, Input>
35	     */
36	    public function inputs(Context $context): array
37	    {
38	        $inputs = [];
39	        foreach ($this->config->documents as $index => $document) {
40	            $inputs['declared' . $index] = new Input(new Selection('files', [$document->path], [], '', false, ''), 'markdown.headings');
41	        }
42	        $inputs['excluded'] = new Input(new Selection('patterns', $context->configuration->scope === null ? $this->config->exclude : [], [], '', false, ''), null);
43	        foreach ($this->config->scan as $index => $pattern) {
44	            $inputs['scan' . $index] = new Input(new Selection('patterns', [$pattern], [], '', false, ''), null);
45	        }
46	        return $inputs;
47	    }
48	    /** Checks declared files first, followed by undeclared files in pattern order.
49	     * @throws RuntimeException
50	     * @throws JsonException
51	     * @throws \Nette\Neon\Exception
52	     */
53	    public function evaluate(InputSet $inputs, Context $context): Plan
54	    {
55	        $violations = [];
56	        foreach ($this->config->documents as $index => $document) {
57	            $value = $inputs->get('declared' . $index)->files[$document->path] ?? null;
58	            if ($value === null) {
59	                continue;
60	            }
61	            if (!$value->file->entry->file) {
62	                $violations[] = (new HeadingViolationFactory())->missingDocument($document->path, $this->config->configName);
63	                continue;
64	            }
65	            if (!$value->readable) {
66	                throw new PolicyException('Cannot read Markdown document: ' . $value->file->path);
67	            }
68	            $list = $value->value();
69	            if (!$list instanceof HeadingList) {
70	                throw new PolicyException('HeadingStructure requires markdown.headings to return HeadingList. Register HeadingStructurer for that structure.');
71	            }
72	            $maxLevel = $document->maxLevel;
73	            $headings = array_values(array_filter($list->all(), static fn (Heading $heading): bool => $heading->level <= $maxLevel));
74	            $violations = array_merge($violations, (new HeadingStructureComparator())->compare($document, $headings, $this->config->configName));
75	        }
76	        $findings = [];
77	        foreach (array_merge($violations, $this->undeclared($inputs)) as $violation) {
78	            $findings[] = new Finding($violation->path, 'documentation.' . $violation->rule, 'required', $violation->message);
79	        }
80	        return new Plan($findings, []);
81	    }
82	    /**
83	     * @return list<HeadingViolation>
84	     */
85	    public function undeclared(InputSet $inputs): array
86	    {
87	        $reported = array_fill_keys(array_keys($inputs->get('excluded')->files), true);
88	        foreach ($this->config->documents as $document) {
89	            $reported[$document->path] = true;
90	        }
91	        $violations = [];
92	        foreach ($this->config->scan as $index => $pattern) {
93	            foreach ($inputs->get('scan' . $index)->files as $file) {
94	                $path = $file->file->relativePath;
95	                if (!isset($reported[$path])) {
96	                    $reported[$path] = true;
97	                    $violations[] = (new HeadingViolationFactory())->undeclaredDocument($path, $pattern, $this->config->configName);
98	                }
99	            }
100	        }
101	        return $violations;
102	    }
103	}
