12	/**
13	 * Creates a versioned guard policy for the tools present in the target project.
14	 */
15	final class Initializer
16	{
17	    /**
18	     * @param ?list<string> $imports null selects presets from the project; a list imports only those names
19	     * @throws PolicyException when guard.yaml exists, cannot be created, or names an unknown preset
20	     * @throws JsonException when composer.json or composer.lock is malformed
21	     */
22	    public function write(string $path, ?array $imports = null): void
23	    {
24	        if (file_exists($path) || is_link($path)) {
25	            throw new PolicyException('Cannot create ' . $path . ': it already exists. Review the existing policy instead of overwriting it.');
26	        }
27	        $data = $this->configuration(dirname($path), $imports);
28	        $source = "# Project policy. Required rules fail; recommendations warn.\n" . Yaml::dump($data, 12, 2, Yaml::DUMP_EMPTY_ARRAY_AS_SEQUENCE);
29	        $handle = @fopen($path, 'x');
30	        if ($handle === false) {
31	            throw new PolicyException('Cannot create ' . $path . '. It must not exist and its directory must be writable.');
32	        }
33	        try {
34	            if (fwrite($handle, $source) !== strlen($source)) {
35	                throw new PolicyException('Could not finish writing ' . $path . '. Check disk space.');
36	            }
37	        } finally {
38	            fclose($handle);
39	        }
40	    }
41	    /**
42	     * Builds a project policy that imports shipped presets and keeps project-specific sections inline.
43	     *
44	     * @param ?list<string> $imports null selects presets from the project; a list imports only those names
45	     * @return array<string, mixed>
46	     * @throws JsonException when composer.json or composer.lock is malformed
47	     * @throws PolicyException when an import name is unknown or a preset cannot be read
48	     */
49	    public function configuration(string $root, ?array $imports = null): array
50	    {
51	        $names = (new PresetSelector())->select($root, $imports);
52	        $document = ['version' => 1];
53	        $paths = (new PresetCatalog())->imports($root, $names);
54	        if ($paths !== []) {
55	            $document['imports'] = $paths;
56	        }
57	        if (in_array('metrics', $names, true)) {
58	            $document['metrics'] = ['source' => (new ToolDetector())->sources($root), 'exclude' => []];
59	        }
60	        $readme = $this->readme($root);
61	        if ($readme !== null) {
62	            $document['documentation'] = $readme;
63	        }
64	        $document = (new PresetOverrides())->apply($root, $names, $document);
65	
66	        return (new LegacyMigration())->migrate($root, $document);
67	    }
68	
69	    /**
70	     * Returns the current README headings when the project has a README.
71	     *
72	     * @return ?array<string, mixed>
73	     */
74	    public function readme(string $root): ?array
75	    {
76	        if (!is_file($root . '/README.md')) {
77	            return null;
78	        }
79	        $source = file_get_contents($root . '/README.md');
80	        $headings = [];
81	        foreach ((new HeadingParser())->parse($source === false ? '' : $source) as $heading) {
82	            $headings[] = $heading->notation();
83	        }
84	
85	        return ['files' => ['README.md' => ['headings' => $headings]], 'scan' => ['README.md']];
86	    }
