88	    /**
89	     * Returns the standard metric limits shipped in rules/metrics.yaml.
90	     *
91	     * @return array<string, array<string, int>>
92	     * @throws PolicyException when metrics.yaml does not define integer limits
93	     */
94	    public function limits(): array
