98	    /**
99	     * @param list<string> $sources
100	     * @return array<string, mixed>
101	     */
102	    public function structure(array $sources, bool $hasUnitTests = false): array
103	    {
104	        $directories = [['path' => '**', 'deny_dirs' => ['scripts', 'Scripts']]];
105	        foreach ($sources as $source) {
106	            $directories[] = ['path' => $source, 'allow' => [], 'max_dirs' => 20];
107	            $directories[] = ['path' => $source . '/**', 'forbid_empty' => true, 'allow' => ['*.php'],
108	                'deny' => ['*Helper.php', '*Helpers.php', '*Manager.php', '*Util.php', '*Utils.php', '*Service.php', '*Evidence.php', '*Evidences.php', '*Outcome.php', '*Outcomes.php', '*Probe.php', '*Probes.php'],
109	                'file_case' => 'pascal', 'dir_case' => 'pascal', 'max_files' => 15, 'max_dirs' => 20];
110	        }
111	        if ($hasUnitTests) {
112	            $directories[] = ['path' => 'tests/Unit', 'allow' => []];
113	            $directories[] = ['path' => 'tests/Unit/**', 'forbid_empty' => true, 'allow' => ['*Test.php'],
114	                'file_case' => 'pascal', 'dir_case' => 'pascal', 'max_files' => 15, 'max_dirs' => 20];
115	        }
116	        $directories[] = ['path' => 'skills/*', 'require' => ['SKILL.md'], 'forbid_empty' => true];
117	        return ['paths' => ['.'], 'exclude' => ['.git', '.idea', '.claude', '.agents', '.codex', '.cursor', '.gemini', '.entire', '.entrie', '.phpunit.cache', 'build', 'projects', 'vendor'], 'directories' => $directories];
118	    }
