10	/**
11	 * Chooses which shipped presets a project imports.
12	 */
13	final class PresetSelector
14	{
15	    /**
16	     * Uses an explicit name list, or the presets that match the project.
17	     *
18	     * loc.yaml and tree.yaml suppress the metrics and structure presets because those files are copied in full.
19	     *
20	     * @param ?list<string> $imports
21	     * @return list<string>
22	     * @throws JsonException when composer.json or composer.lock is malformed
23	     * @throws PolicyException when an explicit name is not a shipped preset
24	     */
25	    public function select(string $root, ?array $imports): array
26	    {
27	        $names = $this->unique($imports ?? $this->detect($root));
28	        foreach ($names as $name) {
29	            (new PresetCatalog())->assertKnown($name);
30	        }
31	        if (is_file($root . '/loc.yaml')) {
32	            $names = $this->without($names, 'metrics');
33	        }
34	        if (is_file($root . '/tree.yaml')) {
35	            $names = $this->without($names, 'structure');
36	        }
37	
38	        return $names;
39	    }
40	
41	    /**
42	     * Detects generic presets from source roots and tool presets from installed configuration.
43	     *
44	     * @return list<string>
45	     * @throws JsonException when composer.json or composer.lock is malformed
46	     */
47	    public function detect(string $root): array
48	    {
49	        $names = [];
50	        if ((new ToolDetector())->sources($root) !== []) {
51	            $names[] = 'metrics';
52	            $names[] = 'structure';
53	        }
54	        foreach ($this->phpstanPresets($root) as $name) {
55	            $names[] = $name;
56	        }
57	        $phpunit = $this->phpunitPresets($root);
58	        foreach ($phpunit as $name) {
59	            $names[] = $name;
60	        }
61	        foreach ($this->doctestPresets($root, $phpunit) as $name) {
62	            $names[] = $name;
63	        }
64	        foreach ($this->toolPresets($root) as $name) {
65	            $names[] = $name;
66	        }
67	        if (is_file($root . '/composer.json')) {
68	            $names[] = 'composer';
69	        }
70	
71	        return $names;
72	    }
73	
74	    /**
75	     * Returns PHPStan presets when a NEON file exists, including toolkit rules when that package is installed.
76	     *
77	     * @return list<string>
78	     * @throws JsonException when composer.json or composer.lock is malformed
79	     */
80	    public function phpstanPresets(string $root): array
81	    {
82	        if ((new Recommendations())->existing($root, ['phpstan.neon', 'phpstan.neon.dist']) === null) {
83	            return [];
84	        }
85	        $names = ['phpstan'];
86	        $packages = (new ToolDetector())->packages($root);
87	        if (isset($packages['k-kinzal/phpstan-guard-rules']) || isset($packages['k-kinzal/php-ai-toolkit'])) {
88	            $names[] = 'phpstan-guard-rules';
89	        }
90	
91	        return $names;
92	    }
93	
94	    /**
95	     * Returns one PHPUnit preset for each versioned file, or the single resolved major.
96	     *
97	     * An unversioned file is PHPUnit 13 when versioned files also exist. A multi-major constraint
98	     * with no lock and no versioned files is not guessed.
99	     *
100	     * @return list<string>
101	     * @throws JsonException when composer.json or composer.lock is malformed
102	     */
103	    public function phpunitPresets(string $root): array
104	    {
105	        $versioned = [
106	            'phpunit9' => ['phpunit9.xml', 'phpunit9.xml.dist'],
107	            'phpunit10' => ['phpunit10.xml', 'phpunit10.xml.dist'],
108	            'phpunit11' => ['phpunit11.xml', 'phpunit11.xml.dist'],
109	            'phpunit12' => ['phpunit12.xml', 'phpunit12.xml.dist'],
110	        ];
111	        $names = [];
112	        foreach ($versioned as $name => $candidates) {
113	            if ((new Recommendations())->existing($root, $candidates) !== null) {
114	                $names[] = $name;
115	            }
116	        }
117	        $plain = (new Recommendations())->existing($root, ['phpunit.xml', 'phpunit.xml.dist']);
118	        if ($names !== []) {
119	            if ($plain !== null) {
120	                $names[] = 'phpunit13';
121	            }
122	
123	            return $names;
124	        }
125	        if ($plain === null) {
126	            return [];
127	        }
128	        $major = $this->phpunitMajor((new ToolDetector())->packages($root)['phpunit/phpunit'] ?? '');
129	        $preset = $major === null ? null : ($major === '13' ? 'phpunit13' : 'phpunit' . $major);
130	        if ($preset === null || !in_array($preset, (new PresetCatalog())->names(), true)) {
131	            return [];
132	        }
133	
134	        return [$preset];
135	    }
136	
137	    /**
138	     * Returns the only PHPUnit major in a lock version or a single-major constraint.
139	     */
140	    public function phpunitMajor(string $version): ?string
141	    {
142	        if (preg_match('/^(\d+)\.\d+/', $version, $locked) === 1) {
143	            return $locked[1];
144	        }
145	        $parts = preg_split('/\s*\|\|\s*/', $version);
146	        $majors = [];
147	        foreach (is_array($parts) ? $parts : [] as $part) {
148	            if (preg_match('/(\d+)/', $part, $match) === 1) {
149	                $majors[$match[1]] = $match[1];
150	            }
151	        }
152	
153	        return count($majors) === 1 ? array_values($majors)[0] : null;
154	    }
155	
156	    /**
157	     * Returns doctest presets for PHPUnit files that already run examples, or when PHPStan requires them.
158	     *
159	     * @param list<string> $phpunit
160	     * @return list<string>
161	     */
162	    public function doctestPresets(string $root, array $phpunit): array
163	    {
164	        $map = [
165	            'phpunit9' => 'doctest9',
166	            'phpunit10' => 'doctest10',
167	            'phpunit11' => 'doctest11',
168	            'phpunit12' => 'doctest12',
169	            'phpunit13' => 'doctest13',
170	        ];
171	        $examples = $this->requiresExamples($root);
172	        $names = [];
173	        foreach ($phpunit as $preset) {
174	            $doctest = $map[$preset] ?? null;
175	            $file = $doctest === null ? null : (new PresetOverrides())->actual($root, $preset);
176	            $source = is_string($file) ? file_get_contents($root . '/' . $file) : false;
177	            if ($doctest !== null && $source !== false && (str_contains($source, 'DoctestSuite') || $examples)) {
178	                $names[] = $doctest;
179	            }
180	        }
181	
182	        return $names;
183	    }
184	
185	    /**
186	     * Reports whether PHPStan is configured to require PHPDoc examples.
187	     */
188	    public function requiresExamples(string $root): bool
189	    {
190	        $file = (new Recommendations())->existing($root, ['phpstan.neon', 'phpstan.neon.dist']);
191	        $source = $file === null ? false : file_get_contents($root . '/' . $file);
192	
193	        return is_string($source) && (str_contains($source, 'allRules: true') || str_contains($source, 'requireExample'));
194	    }
195	
196	    /**
197	     * Returns tool presets whose configuration or package is present.
198	     *
199	     * @return list<string>
200	     * @throws JsonException when composer.json or composer.lock is malformed
201	     */
202	    public function toolPresets(string $root): array
203	    {
204	        $names = [];
205	        $packages = (new ToolDetector())->packages($root);
206	        $existing = new Recommendations();
207	        if ($existing->existing($root, ['.php-cs-fixer.dist.php', '.php-cs-fixer.php']) !== null) {
208	            $names[] = 'php-cs-fixer';
209	        }
210	        if ($existing->existing($root, ['phpcs.xml.dist', 'phpcs.xml']) !== null) {
211	            $names[] = 'phpcs';
212	        }
213	        if (isset($packages['deptrac/deptrac']) && $existing->existing($root, ['deptrac.yaml', 'deptrac.yml']) !== null) {
214	            $names[] = 'deptrac';
215	        }
216	        if (is_file($root . '/infection.json5')) {
217	            $names[] = 'infection';
218	        }
219	        if (is_file($root . '/.github/workflows/ci.yml')) {
220	            $names[] = 'github-actions';
221	        }
222	        if (is_file($root . '/.github/workflows/mutation.yml')) {
223	            $names[] = 'mutation';
224	        }
225	        if (isset($packages['giorgiosironi/eris'])) {
226	            $names[] = 'pbt';
227	        }
228	        if (isset($packages['nikic/php-fuzzer'])) {
229	            $names[] = 'fuzz';
230	        }
231	        if (isset($packages['phpbench/phpbench'])) {
232	            $names[] = 'phpbench';
233	        }
234	        if (isset($packages['k-kinzal/docgen-php']) || $this->packageName($root) === 'k-kinzal/docgen-php') {
235	            $names[] = 'docgen';
236	        }
237	
238	        return $names;
239	    }
240	
241	    /**
242	     * Returns the composer package name.
243	     *
244	     * @throws JsonException when composer.json is malformed
245	     */
246	    public function packageName(string $root): string
247	    {
248	        $name = (new ToolDetector())->manifest($root)['name'] ?? '';
249	
250	        return is_string($name) ? $name : '';
251	    }
252	
253	    /**
254	     * Drops repeated names while keeping the first occurrence.
255	     *
256	     * @param list<string> $names
257	     * @return list<string>
258	     */
259	    public function unique(array $names): array
260	    {
261	        $unique = [];
262	        foreach ($names as $name) {
263	            if (!in_array($name, $unique, true)) {
264	                $unique[] = $name;
265	            }
266	        }
267	
268	        return $unique;
269	    }
270	
271	    /**
272	     * Returns the names except one suppressed preset.
273	     *
274	     * @param list<string> $names
275	     * @return list<string>
276	     */
277	    public function without(array $names, string $suppressed): array
278	    {
279	        $remaining = [];
280	        foreach ($names as $name) {
281	            if ($name !== $suppressed) {
282	                $remaining[] = $name;
283	            }
284	        }
285	
286	        return $remaining;
287	    }
288	}
