26	    /**
27	     * Returns the default configuration file for each tool preset.
28	     *
29	     * @return array<string, string>
30	     */
31	    public function defaults(): array
32	    {
33	        return [
34	            'phpstan' => 'phpstan.neon',
35	            'phpstan-guard-rules' => 'phpstan.neon',
36	            'phpunit9' => 'phpunit9.xml.dist',
