42	            'doctest10' => 'phpunit10.xml.dist',
43	            'doctest11' => 'phpunit11.xml.dist',
44	            'doctest12' => 'phpunit12.xml.dist',
45	            'doctest13' => 'phpunit.xml.dist',
46	            'php-cs-fixer' => '.php-cs-fixer.dist.php',
47	            'phpcs' => 'phpcs.xml.dist',
48	            'deptrac' => 'deptrac.yaml',
49	            'infection' => 'infection.json5',
