60	    /**
61	     * Returns the filenames that satisfy one preset, preferred filename first.
62	     *
63	     * @return list<string>
64	     */
65	    public function candidates(string $preset): array
66	    {
67	        $phpunit = $this->phpunitCandidates($preset);
68	        if ($phpunit !== []) {
69	            return $phpunit;
70	        }
71	        $default = $this->defaults()[$preset] ?? null;
72	        if (!is_string($default)) {
73	            return [];
74	        }
75	
76	        return match ($preset) {
77	            'phpstan', 'phpstan-guard-rules' => ['phpstan.neon', 'phpstan.neon.dist'],
78	            'php-cs-fixer' => ['.php-cs-fixer.dist.php', '.php-cs-fixer.php'],
79	            'phpcs' => ['phpcs.xml.dist', 'phpcs.xml'],
80	            'deptrac' => ['deptrac.yaml', 'deptrac.yml'],
81	            'phpbench' => ['phpbench.json.dist', 'phpbench.json'],
82	            default => [$default],
83	        };
