12	final class Schema
13	{
14	    /**
15	     * @param mixed $value
16	     * @param list<string> $keys
17	     * @return array<string, mixed>
18	     * @throws PolicyException when a mapping contains unknown keys
19	     */
20	    public function mapping($value, array $keys, string $context): array
21	    {
22	        if (!is_array($value) || ($value !== [] && array_values($value) === $value)) {
23	            throw new PolicyException($context . ' must be a mapping.');
24	        }
25	        foreach ($value as $key => $entry) {
26	            if (!is_string($key) || !in_array($key, $keys, true)) {
27	                throw new PolicyException($context . ': unknown key "' . $key . '". Use: ' . implode(', ', $keys) . '.');
28	            }
29	        }
30	        return $value;
31	    }
32	    /**
33	     * @param mixed $value
34	     * @return list<string>
35	     * @throws PolicyException when a path list is invalid
36	     */
37	    public function strings($value, string $context): array
38	    {
39	        if (!is_array($value) || array_values($value) !== $value) {
40	            throw new PolicyException($context . ' must be a list of strings.');
41	        }
42	        $result = [];
43	        foreach ($value as $entry) {
44	            $result[] = $this->string($entry, $context);
45	        }
