    public function inspect(DirectoryRuleConfig $rule, DirectoryListing $listing): array
    {
        $violations = [];
        foreach ($listing->dirNames as $name) {
            $path = $this->pathResolver->child($listing->relativePath, $name);
            foreach ($rule->denyDirs ?? [] as $pattern) {
                if (fnmatch($pattern, $name)) {
                    $violations[] = new DirectoryViolation($path, 'denied_dir', $rule->path, null, null, sprintf('Directory "%s" matches denied pattern "%s". Rename or remove it.', $path, $pattern));
                }
