                $violations[] = new DirectoryViolation($path, 'disallowed_dir', $rule->path, null, null, sprintf('Directory "%s" does not match any allowed pattern (%s). Rename, move, or delete it.', $path, $rule->allowDirs === [] ? 'none' : implode(', ', $rule->allowDirs)));
            }
            if ($rule->dirCase !== null && !str_starts_with($name, '.') && !$this->caseMatcher->matches($rule->dirCase, $name)) {
